@media (max-width: 1050px) {
  .context-bar { grid-template-columns: 1fr 1fr; }
  .context-bar > div:nth-child(2) { border-right: 0px; }
  .context-bar > div:nth-child(-n+2) { border-bottom: 1px solid var(--line); }
  #people:not(.placeholder) { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
}

@media (max-width: 760px) {
  header { padding: 16px 18px; }
  .brand strong { font-size: 22px; }
  .brand small { font-size: 8px; letter-spacing: 1px; max-width: 190px; line-height: 1.5; }
  .mark { display: none; }
  .badge { font-size: 9px; }
  main { padding: 24px 16px 30px; }
  .grid { grid-template-columns: 1fr; gap: 0px; }
  .card { padding: 18px; }
  #evaluate { grid-template-columns: 1fr 1fr; }
  #evaluate .facility-field { grid-column: 1 / -1; }
  .context-bar > div { padding: 13px; }
  .context-bar strong { font-size: 13px; }
  .section-nav { gap: 2px; }
  .section-nav a { font-size: 11px; padding: 8px; }
  footer { padding: 16px; flex-direction: column; gap: 7px; }
  #deployment { max-width: 100%; text-align: left; }
}

@media (max-width: 480px) {
  header { align-items: start; gap: 12px; }
  .badges { justify-content: flex-end; gap: 5px; max-width: 115px; }
  .context-bar { grid-template-columns: 1fr 1fr; }
  .context-bar > div { padding: 12px; border-right: 1px solid var(--line); }
  .context-bar > div:nth-child(2n) { border-right: 0px; }
  .context-bar > div:nth-child(-n+2) { border-bottom: 1px solid var(--line); }
  .context-bar strong { font-size: 12px; }
  .context-bar small { font-size: 10px; }
  #evaluate, #people:not(.placeholder) { grid-template-columns: 1fr; }
  .section-heading { gap: 9px; }
  h2 { font-size: 16px; }
  label { flex-basis: 100%; }
  input, select, textarea { font-size: 16px; }
  #evaluate button, #decision-button { width: 100%; }
  .datum { flex-direction: column; gap: 3px; }
  .datum > span { flex-basis: auto; }
  .datum strong { text-align: left; }
  .big-posture { font-size: 26px; }
}

@media (prefers-reduced-motion: reduce) {
  *, ::before { animation: auto ease 0s 1 normal none running none !important; transition: none !important; }
}

@media (max-width: 1050px) {
  .workflow-nav { grid-template-columns: 1fr 1fr; }
  .next-step { align-items: start; }
  .guide-action { white-space: normal; min-width: 165px; }
}

@media (max-width: 760px) {
  .next-step { flex-direction: column; padding: 16px; gap: 12px; }
  .next-step h2 { font-size: 18px; }
  .workflow-nav a { padding: 10px; font-size: 12px; gap: 8px; }
  .workflow-nav small { font-size: 10px; }
  .workflow-nav b { flex-basis: 24px; height: 24px; }
  .guide-action { min-width: 0px; }
}

@media (max-width: 1050px) {
  .context-bar { grid-template-columns: 1fr 1fr; }
  .workflow-nav { grid-template-columns: repeat(4, minmax(0px, 1fr)); }
  .workflow-nav a { align-items: start; }
  .next-step { align-items: center; }
  .guide-action { min-width: 150px; }
  #decision { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  header { padding: 13px 16px; min-height: 68px; }
  .brand strong { font-size: 21px; }
  .brand small { font-size: 8px; letter-spacing: 0.6px; max-width: 190px; }
  main { padding: 18px 16px 28px; }
  h1 { font-size: 24px; }
  .intro > p:last-of-type { font-size: 12px; }
  .card { padding: 16px; }
  .context-bar > div { padding: 12px; }
  .context-bar strong { font-size: 13px; }
  .context-bar small { font-size: 11px; }
  .next-step { align-items: start; gap: 10px; padding: 12px; }
  .next-step h2 { font-size: 16px; }
  .guide-action { min-width: 0px; max-width: 100%; }
  .workflow-nav { grid-template-columns: 1fr 1fr; }
  .workflow-nav a:nth-child(2) { border-right: 0px; }
  .workflow-nav a:nth-child(-n+2) { border-bottom: 1px solid var(--line); }
  .workflow-nav a { font-size: 12px; padding: 10px; min-height: 54px; }
  .workflow-nav small { font-size: 11px; }
  .decision-grid { grid-template-columns: 1fr; gap: 0px; }
  #evaluate { grid-template-columns: 1fr 1fr; }
  #evaluate button { grid-column: 1 / -1; }
  .person { grid-template-columns: minmax(150px, 0.85fr) minmax(0px, 1.5fr); column-gap: 16px; }
  footer { padding: 16px; }
  .record-links { gap: 14px; }
}

@media (max-width: 480px) {
  .context-bar { grid-template-columns: 1fr; }
  .context-bar > div, .context-bar > div:nth-child(2n) { border-right: 0px; }
  .context-bar > div:not(:last-child) { border-bottom: 1px solid var(--line); }
  .context-bar strong { font-size: 14px; }
  .context-bar small { font-size: 11px; }
  #evaluate, #decision { grid-template-columns: 1fr; }
  #evaluate button, #decision-button { width: 100%; }
  input, select, textarea { font-size: 16px; }
  .big-posture { font-size: 24px; }
  .datum { gap: 3px; }
  .datum > span { flex-basis: auto; }
  .person { display: block; padding: 14px 0px; }
  .person-top { flex-wrap: nowrap; }
  .person > p { margin: 9px 0px 0px; }
  .person-meta { margin: 8px 0px; }
  .person > .follow-up { margin-top: 10px; }
  .person > details { margin-top: 4px; }
  .record-links a { font-size: 11px; }
  header .badges { max-width: 115px; }
  .badge { font-size: 9px; }
}
